  PB.addLabs('chem-mechanisms', [{ sim: 'explore', title: 'Energy profiles: SN1 and SN2', desc: 'A one-step SN2 profile and a two-step SN1 profile through a carbocation intermediate. The highest barrier sets the rate.',
    tasks: ['Raise the carbocation energy (a less stable cation). Which mechanism wins?', 'Which step is rate-determining in SN1?', 'How would a polar protic solvent change the SN1 profile?'],
    params: { controls: [S('a2', 'SN2 barrier', 40, 140, 1, 95, 'kJ/mol'), S('c', 'Carbocation energy', 20, 120, 1, 60, 'kJ/mol'), S('a1', 'Ionisation barrier above start', 40, 140, 1, 85, 'kJ/mol'), S('dH', 'Overall ΔH', -60, 30, 1, -20, 'kJ/mol')],
      init: (v) => { const hump = (x, c, w) => Math.exp(-Math.pow((x - c) / w, 2)); const sm = (x) => 1 / (1 + Math.exp(-x)); v.sn2 = (x) => v.dH * sm((x - 0.5) * 14) + (v.a2 - v.dH / 2) * hump(x, 0.5, 0.13); v.sn1 = (x) => { const base = x < 0.5 ? v.c * sm((x - 0.25) * 18) : v.c + (v.dH - v.c) * sm((x - 0.75) * 18); return base + (v.a1 - v.c / 2) * hump(x, 0.25, 0.07) + (Math.max(5, v.c * 0.25 + 10)) * hump(x, 0.75, 0.06); }; },
      plots: [{ x: [0, 1], y: [-70, 160], xticks: [], xlabel: 'reaction coordinate', ylabel: 'energy (kJ/mol)', curves: (v) => [{ f: (x) => v.sn2(x), label: 'SN2' }, { f: (x) => v.sn1(x), color: 'rust', label: 'SN1' }], n: 400 }],
      readout: (v) => [['SN2 barrier', v.a2 + ' kJ/mol'], ['SN1 rate-determining barrier', v.a1 + ' kJ/mol (ionisation)'], ['faster route', v.a1 < v.a2 ? 'SN1' : 'SN2'], ['rate ratio at 298 K', PB.fmt(Math.exp(Math.abs(v.a2 - v.a1) * 1000 / (8.314 * 298)), 3) + '×']] } }]);

